SINA_SMART["immuno1-mhc"] = {"lecture":"immuno1-mhc","title":"MHC and antigen-presenting cells","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"immuno1-mhc:e0","text":"MHC = HLA in humans; >200 genes; highly polymorphic; graft rejection.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e1","text":"Dausset 1958 (HLA), Nobel 1980; Snell and Gorer (mouse H2).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e2","text":"Class I: all nucleated cells; endogenous peptides (8-10 aa) → CD8.","topic":"MHC classes and structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e3","text":"Class I structure: α chain + β2-microglobulin.","topic":"MHC classes and structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e4","text":"Class II: APCs; exogenous peptides (>13 aa) → CD4; α + β chains.","topic":"MHC classes and structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e5","text":"Class III: complement and inflammatory proteins.","topic":"MHC classes and structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e6","text":"HLA-A, B, C (I); DR, DP, DQ (II); codominant; haplotype inheritance.","topic":"MHC classes and structure","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e7","text":"DCs: sentinels in skin, lung, gut; capture, process, migrate, present.","topic":"Antigen-presenting cells","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e8","text":"Endogenous: proteasome → MHC I; exogenous: lysosome → MHC II.","topic":"Antigen-presenting cells","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e10","text":"One signal only → anergy.","topic":"T-cell activation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-mhc:e9","text":"Signal 1 TCR-MHC; signal 2 B7-CD28, CD40-CD40L; signal 3 IL-12.","topic":"T-cell activation","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"11wvk4j":"a","1rigdtw":"a","meiz9":"a","obtjdh":"a","5liif8":"a","1uquc6g":"a","1qa2r4l":"a","80xyor":"a","19addhm":"a","1b8dbmx":"a","jpo8k":"a","dvac1v":"a","1a1thp2":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"immuno1-mhc:e0":{"s":0,"u":["MHC = HLA in humans; >200 genes; highly polymorphic; graft rejection.","The major histocompatibility complex (MHC) , called HLA (human leukocyte antigen) in humans, was found through graft rejection: Snell and Gorer (1930s, mouse H2) and Jean Dausset (1958, HLA; Nobel Prize 1980). 'Complex': a region of more than 200 genes ; 'major': highly polymorphic , creating differences between individuals; 'histocompatibility': responsible for graft rejection ."],"dp":[]},"immuno1-mhc:e1":{"s":0,"u":["Dausset 1958 (HLA), Nobel 1980; Snell and Gorer (mouse H2).","The major histocompatibility complex (MHC) , called HLA (human leukocyte antigen) in humans, was found through graft rejection: Snell and Gorer (1930s, mouse H2) and Jean Dausset (1958, HLA; Nobel Prize 1980). 'Complex': a region of more than 200 genes ; 'major': highly polymorphic , creating differences between individuals; 'histocompatibility': responsible for graft rejection ."],"dp":[]},"immuno1-mhc:e2":{"s":1,"u":["Class I: all nucleated cells; endogenous peptides (8-10 aa) → CD8.","Class I : on all nucleated cells ; presents endogenous peptides to CD8 T cells ('designates cells to destroy'); a heavy α chain (44 kDa) with β2-microglobulin (11.5 kDa); groove formed by α1 and α2 binds peptides of 8-10 amino acids .","Class II : mainly on APCs ; presents exogenous peptides to CD4 T cells ('designates cells to activate'); α (31-34 kDa) and β (26-29 kDa) chains; groove α1 + β1 binds peptides longer than 13 amino acids ."],"dp":[]},"immuno1-mhc:e3":{"s":1,"u":["Class I structure: α chain + β2-microglobulin.","Class I : on all nucleated cells ; presents endogenous peptides to CD8 T cells ('designates cells to destroy'); a heavy α chain (44 kDa) with β2-microglobulin (11.5 kDa); groove formed by α1 and α2 binds peptides of 8-10 amino acids ."],"dp":[]},"immuno1-mhc:e4":{"s":1,"u":["Class II: APCs; exogenous peptides (>13 aa) → CD4; α + β chains.","Class II : mainly on APCs ; presents exogenous peptides to CD4 T cells ('designates cells to activate'); α (31-34 kDa) and β (26-29 kDa) chains; groove α1 + β1 binds peptides longer than 13 amino acids .","Class I : on all nucleated cells ; presents endogenous peptides to CD8 T cells ('designates cells to destroy'); a heavy α chain (44 kDa) with β2-microglobulin (11.5 kDa); groove formed by α1 and α2 binds peptides of 8-10 amino acids ."],"dp":[]},"immuno1-mhc:e5":{"s":1,"u":["Class III: complement and inflammatory proteins.","Class III : other immune proteins (complement, inflammatory molecules)."],"dp":[]},"immuno1-mhc:e6":{"s":1,"u":["HLA-A, B, C (I); DR, DP, DQ (II); codominant; haplotype inheritance.","Features: the most polymorphic genes of the genome (over 8,000 alleles in 2017; HLA-A, -B, -C for class I; HLA-DR, -DP, -DQ for class II); codominant expression (both parental alleles expressed); inherited as haplotype blocks , one from each parent (Mendelian transmission)."],"dp":[{"h":"Why transplants need HLA matching","t":"HLA genes are extremely polymorphic and codominant, so almost everyone displays a unique set. T cells react strongly against foreign HLA molecules on a graft and reject it. Siblings share both haplotypes with a 1-in-4 chance because haplotypes are inherited as blocks, which is why siblings are the first donors tested for bone marrow transplants, and why unrelated grafts need immunosuppression. Source: the tutorial's MHC characteristics slides."}]},"immuno1-mhc:e7":{"s":2,"u":["DCs: sentinels in skin, lung, gut; capture, process, migrate, present.","DCs (myeloid/conventional and plasmacytoid subtypes) are sentinels concentrated in organs in contact with the outside (skin, lung, gut).","Immature DCs capture antigen by phagocytosis (enhanced by opsonisation), pinocytosis (soluble antigen) and receptor-mediated endocytosis (mannose receptor, Fc receptors, Dectin), process it into peptides, then mature in response to danger signals and migrate to lymph nodes and spleen to present peptide-MHC to naive T cells."],"dp":[]},"immuno1-mhc:e8":{"s":2,"u":["Endogenous: proteasome → MHC I; exogenous: lysosome → MHC II.","Exogenous antigen → endosome/lysosome → MHC II → CD4 ; endogenous antigen → proteasome → ER → MHC I → CD8 ."],"dp":[]},"immuno1-mhc:e10":{"s":3,"u":["One signal only → anergy.","A single signal leads to inactivation or anergy .","At least two signals are needed: signal 1 , TCR recognition of peptide-MHC; signal 2 , co-stimulation : B7 (CD80/CD86) on the APC with CD28 on the T cell, and CD40 on the APC with CD40L on the T cell."],"dp":[]},"immuno1-mhc:e9":{"s":3,"u":["Signal 1 TCR-MHC; signal 2 B7-CD28, CD40-CD40L; signal 3 IL-12.","At least two signals are needed: signal 1 , TCR recognition of peptide-MHC; signal 2 , co-stimulation : B7 (CD80/CD86) on the APC with CD28 on the T cell, and CD40 on the APC with CD40L on the T cell.","Signal 3 , the cytokine environment (e.g."],"dp":[]}},"meta":{"11wvk4j":{"a":"recall","vg":"immuno1-mhc:e0/recall/1"},"1rigdtw":{"a":"recall","vg":"immuno1-mhc:e1/recall/1"},"meiz9":{"a":"recall","vg":"immuno1-mhc:e2/recall/1"},"obtjdh":{"a":"application","vg":"immuno1-mhc:e4/application/1"},"5liif8":{"a":"recall","vg":"immuno1-mhc:e3/recall/1"},"1uquc6g":{"a":"recall","vg":"immuno1-mhc:e2/recall/2"},"1qa2r4l":{"a":"recall","vg":"immuno1-mhc:e6/recall/1"},"80xyor":{"a":"recall","vg":"immuno1-mhc:e5/recall/1"},"19addhm":{"a":"recall","vg":"immuno1-mhc:e6/recall/2"},"1b8dbmx":{"a":"recall","vg":"immuno1-mhc:e7/recall/1"},"jpo8k":{"a":"recall","vg":"immuno1-mhc:e8/recall/1"},"dvac1v":{"a":"recall","vg":"immuno1-mhc:e9/recall/1"},"1a1thp2":{"a":"recall","vg":"immuno1-mhc:e9/recall/2"}},"explRev":"1c176255e1f5"};
